import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 3

def design(feats):
    # Identify strong univariate predictors (p < 0.05)
    strong_uni = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'derived':
            continue  # Skip derived features
        tstat, pval = stats.ttest_ind(feats.x[feats.y==1, i], feats.x[feats.y==0, i])
        if pval < 0.05:
            strong_uni.append((fid, abs(tstat)))

    # Sort by effect size
    strong_uni.sort(key=lambda x: x[1], reverse=True)

    # Check for correlated pairs
    pairs = []
    for i, fid1 in enumerate(feats.ids):
        for j, fid2 in enumerate(feats.ids[i+1:], i+1):
            if feats.types[i] == 'derived' or feats.types[j] == 'derived':
                continue
            corr = np.corrcoef(feats.x[:, i], feats.x[:, j])[0, 1]
            if abs(corr) >= 0.6:
                pairs.append((fid1, fid2, abs(corr)))

    # Sort pairs by correlation strength
    pairs.sort(key=lambda x: x[2], reverse=True)

    # Look for top pairs with strong individual effects
    for fid1, fid2, _ in pairs[:10]:  # Consider top 10 pairs
        idx1 = feats.column(fid1)
        idx2 = feats.column(fid2)

        # Check if both features are strong univariates
        if any(f[0] == fid1 for f in strong_uni[:5]) and any(f[0] == fid2 for f in strong_uni[:5]):
            # Try product term
            prod = feats.x[:, idx1] * feats.x[:, idx2]
            tstat, pval = stats.ttest_ind(prod[feats.y==1], prod[feats.y==0])
            if pval < 0.05:
                return Design(
                    drivers=(fid1, fid2),
                    columns=(fid1, fid2),
                    products=((fid1, fid2),),
                    loadings={fid1: 1.0, fid2: 1.0}
                )

    # If no product found, try single strongest
    if strong_uni:
        fid = strong_uni[0][0]
        return Design(
            drivers=(fid,),
            columns=(fid,),
            products=(),
            loadings={fid: 1.0}
        )

    # No mechanism found
    return Design(
        drivers=(),
        columns=(),
        products=(),
        loadings={}
    )

